const first = $('Query GraphQL').item.json;
const uni = first?.data?.homepageUniverses || {};

function mapProduct(p) {
  return {
    id: String(p.id),
    title: p.title || '',
    year: p.yearOfProduction || null,
    rating: typeof p.rating === 'number' ? p.rating : null,
    wishCount: p.stats?.wishCount ?? 0,
    ratingCount: p.stats?.ratingCount ?? 0,
    poster: p.medias?.picture || '',
    url: p.url ? 'https://www.senscritique.com' + p.url : ''
  };
}

const releases = (uni.newRelease || []).map(mapProduct);
const awaitedSel = (uni.selections || []).find(s => s.label === 'film_attendu');
let awaited = (awaitedSel?.products || []).map(mapProduct);

// Fusionne les dates de sortie recuperees par le node Query Dates
const datesRaw = items[0]?.json?.data || {};
const dateById = {};
for (const key of Object.keys(datesRaw)) {
  const p = datesRaw[key];
  if (p?.id) dateById[String(p.id)] = p.dateReleaseOriginal || null;
}
const today = new Date().toISOString().slice(0, 10);
awaited = awaited.map(f => ({ ...f, releaseDate: dateById[f.id] || null }))
  .filter(f => !f.releaseDate || f.releaseDate >= today);

return [{ json: { releases, awaited, fetchedAt: new Date().toISOString() } }];
